<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { useAuthStore } from '../stores/auth'
const form=reactive({username:'',password:'',nickname:'',studentNo:'',email:''}),loading=ref(false),auth=useAuthStore(),router=useRouter();async function submit(){if(!form.studentNo&&!form.email)return ElMessage.warning('学号或校园邮箱至少填写一项');loading.value=true;try{await auth.register(form);ElMessage.success('注册成功，已获得初始积分');router.replace('/tasks')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
</script>
<template><div class="auth-page"><section class="auth-visual"><div class="brand-mark">C</div><h1>你的技能，<br/>值得被看见。</h1><p>加入可信的校园互助网络，从一次举手之劳开始，遇见更多同路人。</p></section><section class="auth-form-wrap"><div class="auth-form surface"><h2>创建学生账户</h2><p>注册后自动初始化积分与信用档案</p><el-form label-position="top"><div class="register-grid"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="昵称"><el-input v-model="form.nickname"/></el-form-item></div><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password placeholder="至少 6 位"/></el-form-item><el-form-item label="学号"><el-input v-model="form.studentNo"/></el-form-item><el-form-item label="校园邮箱"><el-input v-model="form.email"/></el-form-item><el-button class="full" size="large" type="primary" :loading="loading" @click="submit">注册并进入</el-button></el-form><p style="text-align:center;margin:22px 0 0">已有账号？ <router-link to="/login" style="color:#315f55;font-weight:700">返回登录</router-link></p></div></section></div></template>
<style scoped>.register-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:575px){.register-grid{grid-template-columns:1fr;gap:0}}</style>
